reference_solutions.optimal_java:
public class Solution {
    public int maxDepth(List<Integer> root) {
        if (root == null || root.isEmpty() || root.get(0) == null) return 0;
        return (int) Math.floor(Math.log(root.size()) / Math.log(2)) + 1;
    }
}

